    const result = runner(functions[i++], state, next)
    if (result && typeof result.then === 'function') {
      result.then(handleResolve, handleReject)
    }
  }

  function handleResolve (value) {
    next(null, value)
  }

  function handleReject (err) {
    cb(err, state)
  }

  next()
}

