function buildRequest (R) {
  function _Request (id, params, req, query, headers, log, ip, ips, hostname) {
    this.id = id
    this.params = params
    this.raw = req
    this.query = query
    this.headers = headers
    this.log = log
    this.body = null
    this.ip = ip
    this.ips = ips
    this.hostname = hostname
  }
  _Request.prototype = new R()

  return _Request
}

