  return fn(res, next)
}

function now () {
  var ts = process.hrtime()
  return (ts[0] * 1e3) + (ts[1] / 1e6)
}

function onResponseCallback (err, res) {
  var responseTime = 0

  if (res._startTime) {
    responseTime = now() - res._startTime
  }

